export function normalizeSearch(value: string) {
  return value.trim().toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

export function getLocalizedOptionLabel(
  option: LocalizedLocationOption,
  language: 'th' | 'en',
) {
  return language === 'th' ? option.th : option.en;
}

export function findCountryByValue(value: string) {
  const normalized = normalizeSearch(value);
  return COUNTRY_OPTIONS.find((option) => (
    normalizeSearch(option.value) === normalized
    || normalizeSearch(option.code) === normalized
    || normalizeSearch(option.th) === normalized
    || normalizeSearch(option.en) === normalized
  ));
}

export function findRegionByValue(countryValue: string, regionValue: string) {
  const country = findCountryByValue(countryValue);
  if (!country) return undefined;
  const normalized = normalizeSearch(regionValue);
  return (REGIONS_BY_COUNTRY[country.code] ?? []).find((option) => (
    normalizeSearch(option.value) === normalized
    || normalizeSearch(option.code) === normalized
    || normalizeSearch(option.th) === normalized
    || normalizeSearch(option.en) === normalized
  ));
}

export function getCountryDisplayName(value: string, language: 'th' | 'en') {
  const country = findCountryByValue(value);
  return country ? getLocalizedOptionLabel(country, language) : value;
}

export function getRegionDisplayName(
  countryValue: string,
  regionValue: string,
  language: 'th' | 'en',
) {
  const region = findRegionByValue(countryValue, regionValue);
  return region ? getLocalizedOptionLabel(region, language) : regionValue;
}

export function getCountryRegions(countryValue: string) {
  const country = findCountryByValue(countryValue);
  return country ? (REGIONS_BY_COUNTRY[country.code] ?? []) : [];
}
